import type { Country, NordicCountry } from "../types/game";
import { NORWEGIAN_CITIES } from "./norwayCities";
import { FINNISH_CITIES } from "./finlandCities";
import { DANISH_CITIES } from "./denmarkCities";
import { GERMAN_CITIES } from "./germanyCities";
import { NETHERLANDS_CITIES } from "./netherlandsCities";
import { BELGIAN_CITIES } from "./belgiumCities";
import { LUXEMBOURG_CITIES } from "./luxembourgCities";
import { FRENCH_CITIES } from "./franceCities";
import { ESTONIAN_CITIES } from "./estoniaCities";
import { LATVIAN_CITIES } from "./latviaCities";
import { LITHUANIAN_CITIES } from "./lithuaniaCities";
import { POLISH_CITIES } from "./polandCities";
import { SWISS_CITIES } from "./switzerlandCities";
import { AUSTRIAN_CITIES } from "./austriaCities";
import { HUNGARIAN_CITIES } from "./hungaryCities";
import { ITALIAN_CITIES } from "./italyCities";
import { SPANISH_CITIES } from "./spainCities";

const normalize=(value:string)=>value.normalize("NFKC").toLocaleLowerCase("sv-SE").trim();
const COUNTRY_CITIES:Record<NordicCountry,City[]>={sweden:SWEDISH_CITIES,norway:NORWEGIAN_CITIES,finland:FINNISH_CITIES,denmark:DANISH_CITIES,germany:GERMAN_CITIES,netherlands:NETHERLANDS_CITIES,belgium:BELGIAN_CITIES,luxembourg:LUXEMBOURG_CITIES,france:FRENCH_CITIES,estonia:ESTONIAN_CITIES,latvia:LATVIAN_CITIES,lithuania:LITHUANIAN_CITIES,poland:POLISH_CITIES,switzerland:SWISS_CITIES,austria:AUSTRIAN_CITIES,hungary:HUNGARIAN_CITIES,italy:ITALIAN_CITIES,spain:SPANISH_CITIES};
export function citiesForCountry(country:NordicCountry):City[]{return COUNTRY_CITIES[country]}
export function getCities(country:Country,unlockedCountries:NordicCountry[]=[]):City[]{return[country,...unlockedCountries.filter(item=>item!==country)].flatMap(citiesForCountry)}
export function createCityMap(country:Country):Map<string,City>{return new Map(getCities(country).map(city=>[normalize(city.name),city]))}
export function searchCities(query:string,usedNames:Set<string>,country:Country,unlockedCountries:NordicCountry[]=[],limit=10):City[]{const q=normalize(query);if(!q)return[];const startsWith:City[]=[],contains:City[]=[];for(const city of getCities(country,unlockedCountries)){const lower=normalize(city.name);if(usedNames.has(lower))continue;if(lower.startsWith(q))startsWith.push(city);else if(lower.includes(q))contains.push(city)}return[...startsWith,...contains].slice(0,limit)}
